"""Image-led public practice desk. No private data or generated video required."""
from hashlib import sha256
from html import escape
import re

CSS = '''
.lesson-route{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.lesson-route a{border:1px solid #ffffff26;border-radius:30px;padding:10px 14px;color:#dedee3;font-size:13px;min-height:44px}.lesson-route a:hover{border-color:#ed233a}
.lesson-desk{margin:64px 0;scroll-margin-top:110px}.lesson-desk h2{font-size:clamp(26px,4vw,40px);letter-spacing:-1px}.lesson-desk>p{max-width:760px;color:#b7b7c1;line-height:1.9}.lesson-panel{background:#17171b;border:1px solid #ffffff20;border-radius:12px;padding:24px;margin:20px 0}.lesson-panel h3{margin:0 0 14px;font-size:20px}.lesson-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.lesson-input img{width:100%;aspect-ratio:16/9;object-fit:contain;background:#0e0e11;border-radius:8px}.lesson-input p{color:#bbbcc5;font-size:14px;line-height:1.9}.lesson-steps{counter-reset:input;list-style:none;padding:0;display:grid;gap:12px}.lesson-steps li{counter-increment:input;padding:16px;background:#101013;border-radius:8px;line-height:1.9;color:#c5c5ce}.lesson-steps li:before{content:counter(input,decimal-leading-zero);color:#ed5265;font-family:'Barlow Condensed',sans-serif;font-weight:700;display:block;font-size:22px}.lesson-settings{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.lesson-settings div{padding:16px;background:#101013;border-radius:8px}.lesson-settings dt{font-size:12px;color:#9696a4;margin-bottom:8px}.lesson-settings dd{margin:0;font-size:15px;line-height:1.7}.lesson-repairs{display:grid;grid-template-columns:1fr 1fr;gap:16px}.lesson-repair{border:1px solid #ffffff20;border-radius:12px;padding:22px;background:#17171b}.lesson-repair p{font-size:14px;color:#b9b9c5;line-height:1.9}.lesson-repair pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto;background:#101013;border-radius:8px;padding:16px;font-size:13px;line-height:1.8}.lesson-copy{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:14px 0}.lesson-copy button{border:1px solid #ffffff36;border-radius:6px;padding:11px 16px;color:#fff;background:#25252c;min-height:44px;font:inherit;font-size:13px;cursor:pointer}.lesson-copy button:hover{border-color:#ed5265}.lesson-copy span{color:#bbbcc5;font-size:12px}.lesson-copy button:focus-visible,.lesson-route a:focus-visible{outline:2px solid #ed5265;outline-offset:4px}.lesson-ready{display:grid;gap:12px}.lesson-ready label{display:flex;gap:12px;align-items:flex-start;color:#c8c8d2;line-height:1.8;padding:14px;border:1px solid #ffffff20;border-radius:8px;cursor:pointer}.lesson-ready input{margin-top:5px;accent-color:#ed233a;width:20px;height:20px;flex-shrink:0}.lesson-progress{color:#ed8b98!important}.lesson-image-dialog{padding:16px;background:#101013;color:#fff;border:1px solid #ffffff36;border-radius:12px;max-width:96vw;width:1400px;max-height:94dvh}.lesson-image-dialog::backdrop{background:#000d}.lesson-image-dialog img{width:100%;max-height:78dvh;object-fit:contain}.lesson-image-dialog button{display:block;margin-left:auto;background:#25252c;border:1px solid #777;color:white;border-radius:6px;min-height:44px;padding:10px 16px;cursor:pointer}.lesson-image-dialog p{font-size:13px;color:#bbb}.lesson-desk .tutorial-figure{margin:20px 0}.lesson-media-note{border-left:2px solid #ed233a;padding-left:16px}.lesson-jump{display:inline-flex;margin-top:12px;color:#f0bdc5;text-decoration:underline}
@media(max-width:700px){.lesson-pair,.lesson-repairs{grid-template-columns:1fr}.lesson-settings{grid-template-columns:1fr}.lesson-desk{margin:42px 0}.lesson-panel,.lesson-repair{padding:18px}.lesson-route{gap:7px}.lesson-route a{font-size:12px}.lesson-image-dialog{padding:10px}.lesson-input img{height:auto}.tutorial-main pre{max-width:100%;white-space:pre-wrap;overflow-wrap:anywhere}.tutorial-main{min-width:0}.tutorial-main img{max-width:100%}}
'''

JS = r'''(() => {
const main=document.querySelector('.tutorial-main');if(!main)return;
const en=document.documentElement.lang==='en', t=(ko,english)=>en?english:ko;
main.querySelectorAll('pre').forEach((pre)=>{
  if(!pre.querySelector('code')||pre.closest('[data-no-copy]'))return;
  const row=document.createElement('div');row.className='lesson-copy';
  const button=document.createElement('button');button.type='button';button.textContent=t('프롬프트 복사','Copy prompt');
  const status=document.createElement('span');status.setAttribute('role','status');
  button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(pre.querySelector('code').textContent);status.textContent=t('전문을 복사했습니다.','Full prompt copied.');}catch{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(pre);selection.removeAllRanges();selection.addRange(range);status.textContent=t('선택한 내용을 길게 눌러 복사해 주세요.','Copy the selected text using your browser.');}});
  row.append(button,status);pre.after(row);
});
const checks=Array.from(main.querySelectorAll('.lesson-ready input')),progress=main.querySelector('.lesson-progress');
function update(){if(progress)progress.textContent=t('준비 완료 ','Ready ')+checks.filter(c=>c.checked).length+' / '+checks.length;}
checks.forEach(c=>c.addEventListener('change',update));update();
const dialog=document.createElement('dialog');dialog.className='lesson-image-dialog';dialog.setAttribute('aria-label',t('실습 이미지 크게 보기','Enlarged practice image'));
const close=document.createElement('button');close.type='button';close.textContent=t('닫기 ×','Close ×');
const image=document.createElement('img'),caption=document.createElement('p');dialog.append(close,image,caption);document.body.append(dialog);close.addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
main.querySelectorAll('a[href^="/assets/notes/"]').forEach(link=>{if(!link.querySelector('img'))return;link.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey)return;e.preventDefault();image.src=link.href;image.alt=link.querySelector('img').alt;caption.textContent=image.alt;dialog.showModal();});});
})();'''

def enhance(article, out, t):
    from seedance_tutorial import PROMPT_KO, PROMPT_EN
    assets=out/'assets'/'tutorials';assets.mkdir(parents=True,exist_ok=True)
    css_name='workbench.'+sha256(CSS.encode()).hexdigest()[:12]+'.css'
    js_name='workbench.'+sha256(JS.encode()).hexdigest()[:12]+'.js'
    (assets/css_name).write_text(CSS,encoding='utf-8');(assets/js_name).write_text(JS,encoding='utf-8')
    route='<nav class="lesson-route" aria-label="'+t('실습 순서','Practice order')+'">'+''.join('<a href="#'+anchor+'">'+t(ko,en)+'</a>' for anchor,ko,en in [('scene-examples','01 완성 이미지','01 Scene examples'),('step-1','02 시트 만들기','02 Reference sheet'),('lighting','03 조명 비교','03 Lighting'),('input-desk','04 시댄스 입력','04 Seedance setup'),('repair-desk','05 실패 수정','05 Repairs'),('ready-desk','06 준비 확인','06 Checklist')])+'</nav>'
    pairs=[('character-scene-wide-duchess20-v3-center-soft-wm.webp','이미지 1 · 시작 씬','Image 1 · Opening scene','성의 공간, 인물 위치, 시작 구도와 빛의 방향을 정합니다.','Defines the castle, character position, opening framing and light direction.'),('character-sheet-duchess20-v3-center-soft-wm.webp','이미지 2 · 캐릭터 시트','Image 2 · Character sheet','얼굴·머리·의상만 참고합니다. 시트의 칸 배치와 스튜디오 배경은 가져오지 않습니다.','Defines only face, hair and costume. Do not transfer the panel layout or studio background.')]
    inputs=''.join(f'<article class="lesson-input"><a href="/assets/notes/{img}" target="_blank" rel="noopener"><img src="/assets/notes/{img}" width="1536" height="1024" loading="lazy" decoding="async" alt="{t(ko,en)}"></a><h3>{t(ko,en)}</h3><p>{t(desc,desc_en)}</p></article>' for img,ko,en,desc,desc_en in pairs)
    steps=[('AI 영상 화면에서 사용할 모델과 입력 모드를 먼저 확인합니다. 시작 프레임 한 장만 받는 모드라면 씬 이미지만 첨부합니다. 다중 참고 모드에서 시트도 받는 경우에만 두 번째 이미지를 추가합니다.','Check the model and input mode on the AI Video screen. In a single start-frame mode, attach only the scene. Add the sheet only when the selected reference mode supports it.'),('시작 씬을 먼저, 시트를 다음으로 업로드합니다. 프롬프트 입력창에서 @를 입력하고 실제 첨부 목록에서 씬 이미지를 선택합니다. 시트도 같은 방식으로 선택하세요.','Upload the opening scene first, then the sheet. Type @ in the prompt field and select the actual scene attachment. Select the sheet the same way.'),('아래 전문의 @Image1·@Image2는 설명용 이름입니다. 실제 화면이 만든 이미지 멘션으로 각각 바꿉니다. 글자로만 “이미지 1”을 쓰는 것과 첨부 항목을 선택하는 것은 다릅니다.','The @Image1 and @Image2 labels below are examples. Replace them with the image mentions inserted by your interface. Typing a label as plain text is different from selecting an uploaded attachment.'),('첨부 순서, 인물 고정값, 행동, 카메라, 빛, 소리를 점검한 뒤 설정합니다. 지원되는 길이·해상도·모드만 선택하고, 생성 전에 해당 화면의 크레딧 소모량을 확인하세요. 이 페이지에서 생성은 실행하지 않습니다.','Review attachments, character locks, acting, camera, light and sound. Choose only supported duration, resolution and modes, and check the displayed credit cost before generation. This page does not run generation.')]
    settings=[('화면 비율','Aspect ratio','16:9 · 영화 장면 실습','16:9 · Cinematic exercise'),('길이','Duration','30초 구성안 · 미지원이면 짧은 구간으로 분할','30-second plan · Split into shorter beats if unsupported'),('해상도','Resolution','720p부터 테스트 · 계정에서 제공하는 옵션 확인','Test at 720p if available · Check your account options')]
    setup=f'''<section id="input-desk" class="lesson-desk"><p class="section-eyebrow">04 / INPUT DESK</p><h2>{t('영상 없이도, 입력 방법은 확실하게.','Understand the setup through still images.')}</h2><p>{t('완성 영상 대신 씬 이미지와 스토리보드로 입력 구조를 설명합니다. 아래는 직접 구성한 실습 예시이며, 실제 서비스 화면 캡처나 영상 생성 결과가 아닙니다.','Still scenes and a storyboard explain the setup without a finished video. These are authored teaching examples, not service screenshots or generated video results.')}</p><div class="lesson-panel"><div class="lesson-pair">{inputs}</div></div><div class="lesson-panel"><h3>{t('첨부 → 멘션 → 역할 지정','Attach → Mention → Assign roles')}</h3><ol class="lesson-steps">{''.join('<li>'+t(a,b)+'</li>' for a,b in steps)}</ol><dl class="lesson-settings">{''.join('<div><dt>'+t(a,b)+'</dt><dd>'+t(c,d)+'</dd></div>' for a,b,c,d in settings)}</dl></div><figure class="tutorial-figure"><a href="/assets/notes/seedance-storyboard-v1.webp" target="_blank" rel="noopener"><img src="/assets/notes/seedance-storyboard-v1.webp" width="1536" height="1024" loading="lazy" decoding="async" alt="{t('공간 소개, 시선 이동, 감정 반응의 세 단계 실습 스토리보드','Three-beat teaching storyboard: establish the room, shift the gaze, show the reaction')}"></a><figcaption>{t('공간 소개 → 시선 이동 → 감정 반응. 컷의 의도를 보여주는 이미지 구성안입니다.','Establish → Shift gaze → React. A still-image plan illustrating the intended beats.')}</figcaption></figure><details class="tutorial-prompt"><summary>{t('시댄스 실습 프롬프트 전문 · 복사해서 수정하기','Full Seedance practice prompt · Copy and adapt')}</summary><pre tabindex="0"><code>{t(PROMPT_KO,PROMPT_EN)}</code></pre></details><p class="lesson-media-note">{t('워터마크가 있는 강좌 이미지는 설명용입니다. 실제 생성에는 직접 만든 글씨 없는 원본을 사용하세요. 화면과 옵션은 서비스·계정·업데이트에 따라 달라질 수 있습니다.','Watermarked lesson images are for explanation. Use your own clean originals for generation. Screens and options may vary by service, account and updates.')}</p><a class="lesson-jump" href="/tutorials/seedance-2-5/">{t('시댄스 설정과 작성 방법 더 자세히 보기','Read the detailed Seedance setup and writing guide')} →</a><p><a class="text-button" href="https://dreamina.capcut.com/seedance/how-to-use-seedance-2-5" target="_blank" rel="noopener noreferrer">{t('공식 사용 가이드 확인','Check the official usage guide')} ↗</a></p></section>'''
    repairs=[
      ('얼굴이 다른 사람이 되었을 때','When identity drifts','compare-identity-v1.webp','눈매·코·턱선을 기준 시트와 비교합니다. 기준 얼굴과 수정할 이미지를 함께 첨부하고 얼굴만 수정하세요.','Compare eyes, nose and jawline with the reference. Attach both the reference and the image to repair; target only the face.','첨부한 첫 번째 이미지는 인물의 기준 얼굴이고, 두 번째 이미지는 수정할 씬입니다. 두 번째 이미지의 눈매·코·턱선·얼굴 비율을 첫 번째 기준 얼굴에 맞춰 수정하세요. 긴 갈색 반묶음 머리, 아이보리·파우더 블루 드레스, 티아라, 포즈, 배경, 카메라 구도와 빛은 유지합니다. 다른 인물로 재설계하지 말고 얼굴 수정에만 집중합니다.','The first attached image defines the reference face; the second is the scene to repair. Match the eyes, nose, jawline and facial proportions in the second image to the first. Preserve long brown half-up hair, the ivory and powder-blue gown, tiara, pose, background, framing and light. Repair identity only; do not redesign the character.'),
      ('머리나 신발이 잘렸을 때','When the head or shoes are cropped','compare-crop-v1.webp','전신 시트는 티아라 끝과 구두 끝까지 확인할 수 있어야 합니다. 얼굴을 바꾸기보다 화면 범위부터 수정합니다.','Full-body sheets need visible tiara and shoe tips. Repair the framing before changing the face.','같은 인물과 같은 드레스를 유지한 채 정면 전신 구도를 다시 만드세요. 티아라 끝부터 구두 끝까지 모두 보이게 하고 머리 위와 발 아래에 여백을 확보합니다. 카메라는 눈높이, 인물은 화면 중앙, 단색 회색 배경과 부드러운 중립 조명입니다. 얼굴·머리·의상 장식은 바꾸지 않습니다.','Reframe the same character and gown as a front full-body view. Show everything from the tiara tip to the shoes, leaving space above the head and below the feet. Eye-level camera, centered character, plain gray background and soft neutral light. Preserve face, hair and costume details.'),
      ('색이 너무 쨍하거나 피부가 플라스틱 같을 때','When color is too vivid or skin looks plastic','compare-temperature-v1.webp','빛의 출처를 나누고 피부 결은 남겨 둡니다. 색감과 얼굴을 동시에 바꾸지 않습니다.','Separate light sources and retain skin texture. Do not change color and identity at the same time.','첨부 이미지의 얼굴·의상·포즈·구도를 유지하고 색과 조명만 수정하세요. 낮은 채도, 절제된 명암, 자연스러운 피부 결과 작은 피부 톤 차이를 유지합니다. 창빛은 부드럽고 차갑게, 배경 촛불만 작고 따뜻하게 설정합니다. 과한 오렌지 피부, 네온색, 과도한 선명도, 매끈한 인형 피부와 강한 뷰티 필터를 줄입니다.','Keep the attached face, outfit, pose and framing; adjust only color and lighting. Use restrained saturation and contrast with natural skin texture and subtle tonal variation. Keep window light soft and cool; only the small background candle is warm. Reduce orange skin, neon colors, excessive sharpening, doll-like skin and strong beauty filtering.'),
      ('배경을 바꾸니 옷과 구도까지 바뀔 때','When a new setting changes costume and framing','compare-scene-v1.webp','인물 기준과 공간 기준을 따로 적습니다. 한 번에는 배경 한 항목만 바꿔야 원인을 찾기 쉽습니다.','Separate identity references from setting references. Change only the background first so errors are easier to diagnose.','기준 시트는 얼굴·헤어스타일·아이보리와 파우더 블루 드레스·은빛 자수·티아라의 기준입니다. 시트의 패널 배치와 스튜디오 배경은 사용하지 않습니다. 같은 인물을 성 안의 창가로 옮기되 눈높이 중간 거리, 차분한 표정과 자연스러운 포즈를 유지하세요. 이번 수정에서는 공간만 바꾸고 인물의 디자인은 그대로 유지합니다.','Use the reference sheet only for face, hair, the ivory and powder-blue gown, silver embroidery and tiara. Do not transfer its panel layout or studio background. Move the same character beside a castle window while keeping an eye-level medium shot, calm expression and natural pose. Change only the setting in this revision; preserve the character design.')]
    cards=[]
    for ko,en,img,body,body_en,prompt,prompt_en in repairs:
        cards.append(f'<article class="lesson-repair"><h3>{t(ko,en)}</h3><a href="/assets/notes/{img}" target="_blank" rel="noopener"><img src="/assets/notes/{img}" width="1536" height="1024" loading="lazy" decoding="async" alt="{t(ko,en)}"></a><p>{t(body,body_en)}</p><details><summary>{t("수정 프롬프트 전문","Full repair prompt")}</summary><pre tabindex="0"><code>{t(prompt,prompt_en)}</code></pre></details></article>')
    repair=f'<section class="lesson-desk" id="repair-desk"><p class="section-eyebrow">05 / REPAIR LAB</p><h2>{t("실패했을 때, 한 가지만 바꾸세요.","When it fails, change one thing.")}</h2><p>{t("비교 이미지는 차이를 설명하는 AI 예시입니다. 아래 수정 문장은 직접 작성한 실습 템플릿이며, 도구별 성공을 검증한 결과는 아닙니다. 수정 전 원본을 저장하고 같은 기준으로 비교하세요.","The comparisons are AI teaching illustrations. These authored repair templates are not tool-validated success claims. Save the original and compare each revision against the same reference.")}</p><div class="lesson-repairs">'+''.join(cards)+'</div></section>'
    checklist=[('같은 얼굴·머리·의상으로 시트와 씬이 이어집니다.','The sheet and scene share face, hair and costume.'),('조명 비교에서 무엇을 바꿨는지 설명할 수 있습니다.','I can name what changed in the lighting comparison.'),('이미지 1은 공간, 이미지 2는 인물 기준임을 구분했습니다.','I separated the scene reference from the identity reference.'),('실제 첨부 항목을 선택해 멘션을 넣었습니다.','I selected the actual uploaded assets to insert mentions.'),('한 번에 한 항목을 고치고 원본과 비교합니다.','I repair one variable and compare against the original.'),('생성 전 제공 옵션과 크레딧 소모량을 확인합니다.','I check available options and credit cost before generation.')]
    ready='<section class="lesson-desk lesson-panel" id="ready-desk"><p class="section-eyebrow">06 / READY CHECK</p><h2>'+t('여기까지 이해했다면, 준비 완료.','Understand these steps, and you are ready.')+'</h2><p>'+t('체크는 이 화면에서만 사용하며 서버에 전송하지 않습니다.','Checks are temporary on this page and are not sent to a server.')+'</p><div class="lesson-ready">'+''.join('<label><input type="checkbox">'+t(a,b)+'</label>' for a,b in checklist)+'</div><p class="lesson-progress" role="status" aria-live="polite"></p></section>'
    article=re.sub(r'<nav class="tutorial-toc"[^>]*>.*?</nav>', '', article, count=1, flags=re.S)
    article=article.replace('<section class="tutorial-scenes"',route+'<section class="tutorial-scenes"',1)
    article=article.replace('<aside class="tutorial-ending">',setup+repair+ready+'<aside class="tutorial-ending">',1)
    article=article.replace('</body>',f'<script src="/assets/tutorials/{js_name}" defer></script></body>',1)
    return article, f'<link rel="stylesheet" href="/assets/tutorials/{css_name}">'
